const buffers=new WeakMap();
function bufferFor(context,sample){let cache=buffers.get(context);if(!cache){cache=new Map();buffers.set(context,cache);}if(cache.has(sample.key))return cache.get(sample.key);const binary=atob(sample.pcm),bytes=new Uint8Array(binary.length);for(let i=0;i<binary.length;i++)bytes[i]=binary.charCodeAt(i);const view=new DataView(bytes.buffer),buffer=context.createBuffer(1,bytes.length/2,sample.rate),channel=buffer.getChannelData(0);for(let i=0;i<channel.length;i++)channel[i]=view.getInt16(i*2,true)/32768;let energy=0,peak=0;for(let i=0;i<channel.length;i++){peak=Math.max(peak,Math.abs(channel[i]));if(i<Math.round(sample.rate*.04))energy+=channel[i]*channel[i];}const level=Math.min(.075/Math.sqrt(energy/Math.min(Math.round(sample.rate*.04),channel.length)),.85/Math.max(peak,1e-6));for(let i=0;i<channel.length;i++)channel[i]*=level;cache.set(sample.key,buffer);return buffer;}
