let pitch=state===3?.85:state===2?1.15:1;if(isFirst)pitch*=FIRST_BEAT_RATIO;else if(context.isMainBeat)pitch*=OTHER_STRONG_BEAT_RATIO;source.playbackRate.setValueAtTime(pitch,time);
let volume=state===3?.55:state===2?.50:.45;if(isFirst||context.isOtherStrongBeat)volume*=FIRST_BEAT_VOL;gain.gain.setValueAtTime(volume,time);
